<?php use App\Services\TreatmentGovernanceRules; ?>
<div class="container py-4">
    <h1 class="h3">Treatment review queue</h1>
    <p><a href="<?= e(url('admin/treatments/operations')) ?>">Operations and history</a></p>
    <p class="text-muted">Review only within your recorded qualification scope. Approval passes a KOBI governance revision; it does not publish content or establish clinical effectiveness.</p>
    <form method="get" action="<?= e(url('admin/treatments/review')) ?>" class="card card-body mb-4">
        <div class="row g-3">
            <div class="col-md-4"><label for="review-system" class="form-label">Treatment system</label><select id="review-system" name="treatment_system_id" class="form-select"><option value="">All permitted systems</option><?php foreach ($systems as $system): ?><option value="<?= (int)$system['id'] ?>" <?= ($filters['treatment_system_id']??null)===$system['id'] ? 'selected' : '' ?>><?= e($system['name_en']) ?></option><?php endforeach; ?></select></div>
            <?php foreach (['disease_id'=>'Disease ID','content_revision'=>'Current/submitted revision'] as $field=>$label): ?><div class="col-md-4"><label class="form-label" for="review-<?= e($field) ?>"><?= e($label) ?></label><input class="form-control" id="review-<?= e($field) ?>" type="number" min="1" name="<?= e($field) ?>" value="<?= e((string)($filters[$field]??'')) ?>"></div><?php endforeach; ?>
            <?php foreach (['review_state'=>['pending_review','changes_required','approved'],'evidence_classification'=>TreatmentGovernanceRules::EVIDENCE,'content_purpose'=>TreatmentGovernanceRules::PURPOSE,'due_status'=>['expired','current']] as $field=>$options): ?><div class="col-md-4"><label for="review-<?= e($field) ?>" class="form-label"><?= e(ucfirst(str_replace('_',' ',$field))) ?></label><select class="form-select" id="review-<?= e($field) ?>" name="<?= e($field) ?>"><?php if ($field!=='review_state'): ?><option value="">All</option><?php endif; ?><?php foreach ($options as $option): ?><option value="<?= e($option) ?>" <?= ($filters[$field]??null)===$option ? 'selected' : '' ?>><?= e(str_replace('_',' ',$option)) ?></option><?php endforeach; ?></select></div><?php endforeach; ?>
        </div><div class="mt-3"><button class="btn btn-primary">Filter reviews</button></div>
    </form>
    <div class="table-responsive"><table class="table table-striped align-middle"><caption>Protocols you are authorized to review</caption><thead><tr><th>Protocol</th><th>Disease / system</th><th>Review / publication</th><th>Revision / submission</th><th>Evidence / purpose</th><th>Review due (UTC)</th></tr></thead><tbody>
        <?php foreach ($protocols as $p): ?><tr><td><a href="<?= e(url('admin/treatments/'.$p['id'].'/review')) ?>">#<?= (int)$p['id'] ?> <?= e($p['title_en']??'Untitled') ?></a></td><td><?= e($p['disease_en']) ?><br><?= e($p['system_name']) ?></td><td><?= e($p['review_state']) ?><br><?= e($p['publication_status']) ?></td><td><?= (int)$p['content_revision'] ?><br>Event <?= e((string)($p['submission_id']??'None')) ?></td><td><?= e(str_replace('_',' ',$p['evidence_classification'])) ?><br><?= e(str_replace('_',' ',$p['content_purpose']??'Unassigned')) ?></td><td><?= e($p['review_due_at']??'Not yet approved') ?></td></tr><?php endforeach; ?>
        <?php if (!$protocols): ?><tr><td colspan="6">No reviews match these filters.</td></tr><?php endif; ?>
    </tbody></table></div>
    <nav aria-label="Review pages" class="d-flex gap-2"><?php if ($page>1): ?><a class="btn btn-outline-secondary" href="<?= e(url('admin/treatments/review').'?'.http_build_query(array_replace($filters,['page'=>$page-1]))) ?>">Previous</a><?php endif; ?><?php if ($more): ?><a class="btn btn-outline-secondary" href="<?= e(url('admin/treatments/review').'?'.http_build_query(array_replace($filters,['page'=>$page+1]))) ?>">Next</a><?php endif; ?></nav>
</div>
